select ca.application_id, ca.application_id as issuance_id, COALESCE(ca.certificate_id, CONCAT('CERT_', ca.application_id)) as certificate_number, -- 使用申请表的certificate_id ca.application_content as certificate_content, COALESCE(ca.approve_time, ca.create_time) as issuance_time, NULL as expiry_date, ca.create_by, ca.create_time, ca.update_by, ca.update_time, ca.remark, ct.template_name, ct.certificate_type, CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."院校"')) IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."院校"')) != '' THEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."院校"')) WHEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."企业"')) IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."企业"')) != '' THEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."企业"')) ELSE '无' END as company, ca.application_data as applicationData, CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有\u0004效\u0004期\u0004"')) IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有\u0004效\u0004期\u0004"')) != '' THEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有\u0004效\u0004期\u0004"')) WHEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有效期"')) IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有效期"')) != '' THEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有效期"')) ELSE COALESCE(ca.approve_time, ca.create_time) END as valid_from, CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有\u0004效\u0004期\u0004"')) IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有\u0004效\u0004期\u0004"')) != '' THEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有\u0004效\u0004期\u0004"')) WHEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有效期"')) IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有效期"')) != '' THEN JSON_UNQUOTE(JSON_EXTRACT(ca.application_data, '$."有效期"')) ELSE NULL END as valid_to, COALESCE(ca.receive_status, 'not_received') as receive_status, ca.application_status, su.user_name as applicant_name from certificate_application ca left join certificate_template ct on ca.template_id = ct.template_id left join sys_user su on ca.user_id = su.user_id
AND ca.application_status = #{applicationStatus}
AND ca.template_id = #{templateId}
AND ca.user_id = #{userId}
AND ct.certificate_type = #{certificateType}
AND ca.create_by = #{createBy}
AND ca.application_status >= '2' -- 只查询已批准及以上的申请（状态2及以上）
order by ca.create_time desc
